<?php
declare(strict_types=1);
header('Content-Type: application/json; charset=utf-8');require_once __DIR__.'/../config/auth.php';auth_require(['ADMIN','VERIFICADOR']);$c=require __DIR__.'/../config/database.php';$pdo=new PDO("mysql:host={$c['host']};dbname={$c['dbname']};charset={$c['charset']}",$c['user'],$c['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);function out(array$d,int$c=200):never{http_response_code($c);echo json_encode($d,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
try{$clave=auth_resolve_sede_clave((string)($_GET['sede']??'MONTEVERDE'));$st=$pdo->prepare('SELECT * FROM sedes WHERE clave=:c AND activo=1');$st->execute([':c'=>$clave]);$s=$st->fetch();if(!$s)out(['ok'=>false,'error'=>'Sede inválida'],422);$sid=$s['id'];$hoy=new DateTimeImmutable('today');$mes=(int)$hoy->format('n');$anio=(int)$hoy->format('Y');$alertas=[];
// Los registros públicos son alerta administrativa prioritaria durante 7 días.
if(auth_user()['rol']==='ADMIN'){try{$st=$pdo->prepare("SELECT rp.alumno_id,rp.tipo,rp.created_at,a.nombre FROM registros_publicos rp JOIN alumnos a ON a.id=rp.alumno_id WHERE rp.sede_id=:s AND rp.created_at>=DATE_SUB(NOW(),INTERVAL 7 DAY) AND a.estado_administrativo='PENDIENTE' ORDER BY rp.created_at DESC");$st->execute([':s'=>$sid]);foreach($st as$r)$alertas[]=['tipo'=>'NUEVO_USUARIO','nivel'=>'ALTA','titulo'=>'🚨 Nuevo usuario registrado','detalle'=>$r['nombre'].' · '.($r['tipo']==='INTENSIVO'?'Intensivo':'Regular').' · '.$s['nombre'],'href'=>'/ficha-alumno.php?id='.rawurlencode((string)$r['alumno_id'])];}catch(Throwable$_){}}
$st=$pdo->prepare("SELECT COUNT(*) FROM alumnos a WHERE a.sede_id=:s AND a.estado_administrativo='ACTIVO' AND a.plan_actual_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM mensualidades m WHERE m.alumno_id=a.id AND m.sede_id=:sm AND m.mes=:m AND m.anio=:a AND m.estado='PAGADA') AND NOT EXISTS(SELECT 1 FROM curso_intensivo_alumnos cia JOIN cursos_intensivos ci ON ci.id=cia.curso_intensivo_id WHERE cia.alumno_id=a.id AND ci.sede_id=:sc AND ci.estado IN ('PROGRAMADO','EN_CURSO'))");$st->execute([':s'=>$sid,':sm'=>$sid,':m'=>$mes,':a'=>$anio,':sc'=>$sid]);$n=(int)$st->fetchColumn();if($n)$alertas[]=['tipo'=>'PAGO','nivel'=>'ALTA','titulo'=>"$n alumno".($n===1?'':'s').' sin mensualidad del mes','detalle'=>'Revisar pagos pendientes antes de permitir acceso a clase.','href'=>'/alumnos.php?alerta=sin_pago&sede='.rawurlencode($clave)];
$man=$hoy->modify('+1 day')->format('Y-m-d');$st=$pdo->prepare("SELECT COUNT(*) FROM avisos_ausencia aa JOIN alumnos a ON a.id=aa.alumno_id WHERE a.sede_id=:s AND aa.estado='ACTIVO' AND :f BETWEEN aa.fecha_desde AND aa.fecha_hasta");$st->execute([':s'=>$sid,':f'=>$man]);$n=(int)$st->fetchColumn();if($n)$alertas[]=['tipo'=>'AUSENCIA','nivel'=>'MEDIA','titulo'=>"$n aviso".($n===1?'':'s').' de ausencia para mañana','detalle'=>'La asistencia los marcará como justificadas si no se presentan.','href'=>'/ausencias.php?alerta=manana&sede='.rawurlencode($clave)];
$st=$pdo->prepare("SELECT COUNT(*) FROM reposiciones_regulares rr JOIN alumnos a ON a.id=rr.alumno_id WHERE rr.estado='DISPONIBLE' AND a.sede_id=:s");$st->execute([':s'=>$sid]);$n=(int)$st->fetchColumn();if($n)$alertas[]=['tipo'=>'REPOSICION','nivel'=>'BAJA','titulo'=>"$n reposición".($n===1?'':'es').' disponible'.($n===1?'':'s'),'detalle'=>'Hay reposiciones pendientes de asignar o utilizar.','href'=>'/ausencias.php?alerta=reposiciones&sede='.rawurlencode($clave)];
$dias=(int)($pdo->query("SELECT valor FROM configuracion WHERE clave='alerta_dias_fin_intensivo' LIMIT 1")->fetchColumn()?:7);$lim=$hoy->modify("+$dias days")->format('Y-m-d');$st=$pdo->prepare("SELECT id,fecha_fin FROM cursos_intensivos WHERE sede_id=:s AND estado='EN_CURSO' AND fecha_fin BETWEEN :h AND :l ORDER BY fecha_fin");$st->execute([':s'=>$sid,':h'=>$hoy->format('Y-m-d'),':l'=>$lim]);foreach($st as$r)$alertas[]=['tipo'=>'INTENSIVO','nivel'=>'MEDIA','titulo'=>'Intensivo termina el '.date('d/m',strtotime($r['fecha_fin'])),'detalle'=>'Revisar continuidad de participantes y reposiciones.','href'=>'/intensivo-detalle.php?id='.rawurlencode((string)$r['id']).'&sede='.rawurlencode($clave)];
if($s['minimo_mensual_socio']!==null){$periodo=$hoy->format('Y-m');[$yy,$mm]=array_map('intval',explode('-',$periodo));$d=$periodo.'-01';$h=$hoy->modify('last day of this month')->format('Y-m-d');$sql="SELECT COALESCE(SUM(CASE WHEN p.tipo='MENSUALIDAD' THEN p.importe*:pm WHEN p.tipo='INTENSIVO' THEN p.importe*:pi WHEN p.tipo='INSCRIPCION' THEN p.importe*:pins ELSE 0 END),0) FROM pagos p LEFT JOIN mensualidades m ON m.id=p.mensualidad_id LEFT JOIN cursos_intensivos ci ON ci.id=p.intensivo_id LEFT JOIN inscripciones i ON i.id=p.inscripcion_id WHERE p.estado='VALIDO' AND ((p.tipo='MENSUALIDAD' AND m.sede_id=:sm AND m.mes=:mes AND m.anio=:anio) OR (p.tipo='INTENSIVO' AND ci.sede_id=:sc AND ci.fecha_inicio BETWEEN :dc AND :hc) OR (p.tipo='INSCRIPCION' AND i.sede_id=:si AND i.fecha BETWEEN :di AND :hi))";$st=$pdo->prepare($sql);$st->execute([':pm'=>(float)$s['porcentaje_mensualidad_socio']/100,':pi'=>(float)$s['porcentaje_intensivo_socio']/100,':pins'=>(float)$s['porcentaje_inscripcion_socio']/100,':sm'=>$sid,':mes'=>$mm,':anio'=>$yy,':sc'=>$sid,':dc'=>$d,':hc'=>$h,':si'=>$sid,':di'=>$d,':hi'=>$h]);$a=(float)$st->fetchColumn();$min=(float)$s['minimo_mensual_socio'];$alertas[]=['tipo'=>'SOCIO','nivel'=>$a>=$min?'OK':'BAJA','titulo'=>$a>=$min?'Mínimo '.$s['socio'].' alcanzado ✓':'Mínimo '.$s['socio'].' en progreso','detalle'=>$a>=$min?'Las comisiones del próximo mes quedan habilitadas.':'Aporte actual: $'.number_format($a,0).' de $'.number_format($min,0).'.','href'=>'/reportes.php?periodo='.rawurlencode($periodo).'&sede='.rawurlencode($clave)];}out(['ok'=>true,'sede'=>$clave,'total'=>count($alertas),'alertas'=>$alertas]);}catch(Throwable$e){out(['ok'=>false,'error'=>$e->getMessage()],500);}